/// <summary>
/// PricingAttribute of table <c>WHSInventTable</c> field UOMSeqGroupId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeWHSInventTableUOMSeqGroupId extends UPSPricingAttributeWHSInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(WHSInventTable, UOMSeqGroupId);
}

public Set getAllowedValues()
{
    var            ret = new Set(Types::String);
    WHSInventTable wHSInventTable;

    while select wHSInventTable
        group by UOMSeqGroupId
    {
        if (! ret.in(wHSInventTable.UOMSeqGroupId))
        {
            ret.add(wHSInventTable.UOMSeqGroupId);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(WHSInventTable, UOMSeqGroupId));
    qbr.value(queryValue(_value));
}
